corrected_code:
package inventory

import (
	"context"
	"google.golang.org/grpc/codes"
	"google.golang.org/grpc/status"
	invpb "myapp/gen/inventory/v1"
	"myapp/auth"
	"myapp/warehouse"
)

type InventoryServer struct {
	invpb.UnimplementedInventoryServiceServer
	Manager warehouse.StockManager
}

func (s *InventoryServer) ReserveWarehouseStock(ctx context.Context, req *invpb.ReserveStockRequest) (*invpb.ReserveStockResponse, error) {
	authMerchantID, ok := auth.GetMerchantIDFromContext(ctx)
	if !ok {
		return nil, status.Error(codes.Unauthenticated, "Merchant credentials required")
	}

	if authMerchantID != req.GetMerchantId() {
		return nil, status.Error(codes.PermissionDenied, "Cannot reserve inventory for another merchant")
	}

	reservationID, err := s.Manager.Reserve(ctx, authMerchantID, req.GetSku(), req.GetQuantity())
	if err != nil {
		return nil, status.Errorf(codes.FailedPrecondition, "Reservation failed: %v", err)
	}

	return &invpb.ReserveStockResponse{ReservationId: reservationID}, nil
}
